#!/usr/bin/env node
/**
 * stdio bridge for the Marka MCP server.
 *
 * Claude Desktop (and any other client without an HTTP transport) spawns this as a subprocess and
 * speaks MCP over stdin/stdout. Clients that DO speak streamable HTTP should point at Marka's
 * hosted gateway instead — `getMcpServerConfig()` emits both snippets.
 *
 * This file is the credential boundary on purpose. Package source never reads `process.env` (the
 * marka/no-process-env rule, and a library that reaches for ambient config is unusable in a
 * browser or a multi-tenant server); a bin is an application of its own, so the key is resolved
 * HERE and handed to the library as an argument. That is why this one file is on the R5 allowlist
 * in eslint.config.mjs.
 *
 * Usage:
 *   marka-mcp-stdio --api-key=mk_… [--base-url=https://joinmarka.com]
 *   MARKA_API_KEY=mk_… marka-mcp-stdio
 *
 * TWO WAYS THIS FILE RUNS. Published, it is compiled to `dist/bin/mcp-stdio.js` and runs under
 * plain `node` with no loader — which is what makes `npx -p @joinmarka/sdk marka-mcp-stdio` work.
 * Inside the monorepo the workspace package still exports TypeScript source, so `bin/mcp-stdio.mjs`
 * registers tsx's ESM loader and imports THIS file. One implementation, two entry paths.
 */
import { createMarkaMcpServer } from "../mcp";

/** `--api-key=mk_…` → `mk_…`; also accepts the two-token `--api-key mk_…` spelling. */
function readFlag(argv: readonly string[], name: string): string | undefined {
  const prefixed = argv.find((arg) => arg.startsWith(`--${name}=`));
  if (prefixed !== undefined) return prefixed.slice(`--${name}=`.length);
  const index = argv.indexOf(`--${name}`);
  if (index !== -1 && index + 1 < argv.length) return argv[index + 1];
  return undefined;
}

const argv = process.argv.slice(2);

if (argv.includes("--help") || argv.includes("-h")) {
  process.stdout.write(
    "marka-mcp-stdio — Marka MCP server over stdio\n\n" +
      "  --api-key=<key>    Marka API key (or set MARKA_API_KEY)\n" +
      "  --base-url=<url>   API origin, scheme and host only (or set MARKA_BASE_URL)\n",
  );
  process.exit(0);
}

const apiKey = readFlag(argv, "api-key") ?? process.env.MARKA_API_KEY;
const baseUrl = readFlag(argv, "base-url") ?? process.env.MARKA_BASE_URL;

if (apiKey === undefined || apiKey === "") {
  // stderr, never stdout: stdout is the MCP transport, and prose written there corrupts the
  // JSON-RPC stream the client is parsing.
  process.stderr.write("marka-mcp-stdio: no API key. Pass --api-key=mk_… or set MARKA_API_KEY.\n");
  process.exit(1);
}

const server = createMarkaMcpServer(baseUrl === undefined ? { apiKey } : { apiKey, baseUrl });

await server.startStdio();
